create or replace function private.notes_can_access_folder(p_folder_id uuid,p_user_id uuid default auth.uid())
returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select private.is_approved_user() and p_folder_id is not null and (private.notes_is_platform_owner(p_user_id)
or exists(with recursive ancestors(id,parent_folder_id,owner_id) as (select f.id,f.parent_folder_id,f.owner_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id,parent.owner_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from ancestors a where a.owner_id=p_user_id)
or exists(with recursive ancestors(id,parent_folder_id) as (select f.id,f.parent_folder_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from public.notes_collaborators c join ancestors a on a.id=c.folder_id where c.resource_type='FOLDER' and c.invited_user_id=p_user_id and c.status='ACCEPTED'));$$;
create or replace function private.notes_can_access_document(p_document_id uuid,p_user_id uuid default auth.uid())
returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select private.is_approved_user() and p_document_id is not null and (private.notes_is_platform_owner(p_user_id) or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.owner_id=p_user_id) or exists(select 1 from public.notes_collaborators c where c.resource_type='DOCUMENT' and c.document_id=p_document_id and c.invited_user_id=p_user_id and c.status='ACCEPTED') or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.folder_id is not null and private.notes_can_access_folder(d.folder_id,p_user_id)));$$;
create or replace function private.notes_can_edit_folder(p_folder_id uuid,p_user_id uuid default auth.uid())
returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select private.is_approved_user() and p_folder_id is not null and (exists(with recursive ancestors(id,parent_folder_id,owner_id) as (select f.id,f.parent_folder_id,f.owner_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id,parent.owner_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from ancestors a where a.owner_id=p_user_id) or exists(with recursive ancestors(id,parent_folder_id) as (select f.id,f.parent_folder_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from public.notes_collaborators c join ancestors a on a.id=c.folder_id where c.resource_type='FOLDER' and c.invited_user_id=p_user_id and c.status='ACCEPTED'));$$;
create or replace function private.notes_can_manage_folder(p_folder_id uuid,p_user_id uuid default auth.uid())
returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select private.is_approved_user() and p_folder_id is not null and exists(with recursive ancestors(id,parent_folder_id,owner_id) as (select f.id,f.parent_folder_id,f.owner_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id,parent.owner_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from ancestors a where a.owner_id=p_user_id);$$;
create or replace function private.notes_can_manage_document(p_document_id uuid,p_user_id uuid default auth.uid())
returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select private.is_approved_user() and p_document_id is not null and (exists(select 1 from public.notes_documents d where d.id=p_document_id and d.owner_id=p_user_id) or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.folder_id is not null and private.notes_can_manage_folder(d.folder_id,p_user_id)));$$;
create or replace function private.notes_can_edit_document(p_document_id uuid,p_user_id uuid default auth.uid())
returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select private.is_approved_user() and p_document_id is not null and (private.notes_can_manage_document(p_document_id,p_user_id) or exists(select 1 from public.notes_collaborators c where c.resource_type='DOCUMENT' and c.document_id=p_document_id and c.invited_user_id=p_user_id and c.status='ACCEPTED') or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.folder_id is not null and private.notes_can_edit_folder(d.folder_id,p_user_id)));$$;
drop policy notes_folders_insert_access on public.notes_folders;
create policy notes_folders_insert_access on public.notes_folders for insert to authenticated with check(private.is_approved_user() and owner_id=(select auth.uid()) and (parent_folder_id is null or private.notes_can_edit_folder(parent_folder_id,(select auth.uid()))));
drop policy notes_folders_update_owner on public.notes_folders;
create policy notes_folders_update_owner on public.notes_folders for update to authenticated using(private.is_approved_user() and private.notes_can_manage_folder(id,(select auth.uid()))) with check(private.is_approved_user() and private.notes_can_manage_folder(id,(select auth.uid())));
drop policy notes_folders_delete_owner on public.notes_folders;
create policy notes_folders_delete_owner on public.notes_folders for delete to authenticated using(private.is_approved_user() and private.notes_can_manage_folder(id,(select auth.uid())));
drop policy notes_documents_insert_access on public.notes_documents;
create policy notes_documents_insert_access on public.notes_documents for insert to authenticated with check(private.is_approved_user() and owner_id=(select auth.uid()) and (folder_id is null or private.notes_can_edit_folder(folder_id,(select auth.uid()))));
drop policy notes_documents_update_access on public.notes_documents;
create policy notes_documents_update_access on public.notes_documents for update to authenticated using(private.is_approved_user() and private.notes_can_edit_document(id,(select auth.uid()))) with check(private.is_approved_user() and private.notes_can_edit_document(id,(select auth.uid())));
drop policy notes_documents_delete_owner on public.notes_documents;
create policy notes_documents_delete_owner on public.notes_documents for delete to authenticated using(private.is_approved_user() and (owner_id=(select auth.uid()) or (folder_id is not null and private.notes_can_manage_folder(folder_id,(select auth.uid())))));
drop policy notes_collaborators_read_participant on public.notes_collaborators;
create policy notes_collaborators_read_participant on public.notes_collaborators for select to authenticated using(private.is_approved_user() and (invited_user_id=(select auth.uid()) or owner_id=(select auth.uid()) or invited_by=(select auth.uid()) or private.notes_is_platform_owner((select auth.uid())) or (folder_id is not null and private.notes_can_manage_folder(folder_id,(select auth.uid()))) or (document_id is not null and private.notes_can_manage_document(document_id,(select auth.uid())))));
